'use client'

import { useCallback, useState } from 'react'
import VideoDownloader from './VideoDownloader'

export default function HomeTab() {
  const [link, setLink] = useState('')
  const [message, setMessage] = useState<string | null>(null)

  // Simula pegar o link da área de transferência
  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText()
      if (!text) {
        setMessage('Nenhum link encontrado na área de transferência.')
        return
      }
      setLink(text)
      setMessage(null)
      // Aqui você pode chamar uma função para detectar a plataforma e abrir a janela de download
      // Exemplo: detectPlatformAndOpen(text)
    } catch {
      setMessage('Não foi possível acessar a área de transferência.')
    }
  }

  // Em app desktop, estes botões chamariam funções nativas.
  // Na web, você pode simular fechar/minimizar/maximizar (ex: esconder app, fullscreen, etc).
  const handleClose = useCallback(() => {
    // window.close() só funciona em janelas abertas via script
    alert('Fechar janela (simulado)')
  }, [])

  const handleMinimize = useCallback(() => {
    alert('Minimizar janela (simulado)')
  }, [])

  const handleMaximize = useCallback(() => {
    alert('Maximizar janela (simulado)')
  }, [])

  return (
    <div className="flex items-center justify-between h-10 px-4 bg-white/80 dark:bg-gray-900/80 border-b border-gray-200 dark:border-gray-800 rounded-t-lg select-none" style={{ WebkitAppRegion: 'drag' } as any}>
      <div className="flex items-center gap-2">
        <img src="/icon.png" alt="Logo" className="h-6" />
        <span className="font-semibold text-gray-700 dark:text-gray-200">TriviD</span>
      </div>
      <div className="flex gap-2" style={{ WebkitAppRegion: 'no-drag' } as any}>
        <button onClick={handleMinimize} className="w-6 h-6 rounded hover:bg-gray-200 dark:hover:bg-gray-700 flex items-center justify-center" title="Minimizar">
          <img src="/icons/minimize.svg" alt="Minimize" className="w-4 h-4" />
        </button>
        <button onClick={handleMaximize} className="w-6 h-6 rounded hover:bg-gray-200 dark:hover:bg-gray-700 flex items-center justify-center" title="Maximizar">
          <img src="/icons/maximize.svg" alt="Maximize" className="w-4 h-4" />
        </button>
        <button onClick={handleClose} className="w-6 h-6 rounded hover:bg-red-500 flex items-center justify-center" title="Fechar">
          <img src="/icons/close.svg" alt="Close" className="w-4 h-4" />
        </button>
      </div>
      <div className="space-y-6">
        {/* Seção principal de download */}
        <VideoDownloader />
        
        {/* Seção de recursos */}
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700 p-6">
          <h2 className="text-xl font-semibold mb-4 text-gray-900 dark:text-gray-100">
            Recursos Disponíveis
          </h2>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
              <div className="text-2xl mb-2">🎥</div>
              <h3 className="font-medium text-gray-900 dark:text-gray-100 mb-1">Vídeo HD</h3>
              <p className="text-sm text-gray-600 dark:text-gray-400">Downloads até 1080p</p>
            </div>
            
            <div className="text-center p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
              <div className="text-2xl mb-2">🎵</div>
              <h3 className="font-medium text-gray-900 dark:text-gray-100 mb-1">Áudio MP3</h3>
              <p className="text-sm text-gray-600 dark:text-gray-400">Qualidade até 320kbps</p>
            </div>
            
            <div className="text-center p-4 bg-gray-50 dark:bg-gray-700 rounded-lg">
              <div className="text-2xl mb-2">⚡</div>
              <h3 className="font-medium text-gray-900 dark:text-gray-100 mb-1">Download Rápido</h3>
              <p className="text-sm text-gray-600 dark:text-gray-400">Processamento otimizado</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}